window.RETH_PACK = {"repository":"paradigmxyz/reth","commit":"3d592ece6de8c4559987416a544fc215fd6d6921","commitDate":"2026-09-28","sourceStatus":"commit-pinned","topic":"eth_sendRawTransaction → transaction pool","conditions":["転送先なしの通常経路を中心に読む","blob sidecar の変換処理は折りたたみ","静的なコード読解。ノードやテストは未実行"],"steps":[{"id":"rpc","path":"crates/rpc/rpc-eth-api/src/core.rs","file":"core.rs","start":920,"end":924,"code":"    /// Handler for: `eth_sendRawTransaction`\n    async fn send_raw_transaction(&self, tx: Bytes) -> RpcResult<B256> {\n        trace!(target: \"rpc::eth\", ?tx, \"Serving eth_sendRawTransaction\");\n        Ok(EthTransactions::send_raw_transaction(self, tx).await?)\n    }","sourceUrl":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc-eth-api/src/core.rs#L920-L924","contentHash":"bed3557bb9602e7337d6c7249cd3e0b53870c86f15ff7896dcf186b648322b9f","title":"RPC の入口を読む","question":"署名済みトランザクションは、どこへ渡る？","subtitle":"eth_sendRawTransaction のハンドラーから、共通ヘルパーへの委譲を追います。","symbol":"send_raw_transaction","node":"RPC の入口","short":"入口と委譲","lines":[921,923],"summary":"RPC ハンドラーは、共通のトランザクション処理へ委譲します。","detail":"受け取った Bytes を EthTransactions::send_raw_transaction に渡し、結果を待ちます。成功時は B256 のハッシュを RPC の結果として返します。","input":"署名済みトランザクションのバイト列（Bytes）","output":"RpcResult<B256>：成功時はハッシュ","side":"トレースログの記録、ヘルパーの呼び出し","branch":"await? で失敗を呼び出し元へ伝播します。成功はブロック取り込みの完了を意味しません。","concept":".await? と Ok(...)","language":"await で Future の結果を待ち、その Result に ? を適用します。Ok なら値を取り出し、Err なら必要な型変換を行って呼び出し元へ返します。","compare":"TypeScript の await に似ていますが、Result の Err は Promise の reject とは別の値です。? がエラーの早期返却を明示します。","doc":"https://doc.rust-lang.org/book/ch09-02-recoverable-errors-with-result.html","related":"rpc-contract","group":"RPC","edge":"ヘルパーへ委譲","edgeLine":923},{"id":"recover","path":"crates/rpc/rpc-eth-api/src/helpers/transaction.rs","file":"transaction.rs","start":81,"end":109,"code":"    /// Decodes and recovers the transaction and submits it to the pool.\n    ///\n    /// Returns the hash of the transaction.\n    fn send_raw_transaction(\n        &self,\n        tx: Bytes,\n    ) -> impl Future<Output = Result<B256, Self::Error>> + Send {\n        async move {\n            let pool_transaction = self.recover_raw_pool_transaction(&tx)?;\n            self.send_pool_transaction(\n                TransactionOrigin::Local,\n                WithEncoded::new(tx, pool_transaction),\n            )\n            .await\n        }\n    }\n\n    /// Decodes and recovers a raw pool transaction, sharing sender recovery when configured.\n    fn recover_raw_pool_transaction(&self, tx: &[u8]) -> Result<PoolTx<Self::Pool>, Self::Error> {\n        match self.eth_api_settings().sender_recovery_cache.as_ref() {\n            Some(cache) => {\n                <PoolTx<Self::Pool> as PoolTransaction>::recover_raw_transaction_with_cache(\n                    tx, cache,\n                )\n            }\n            None => <PoolTx<Self::Pool> as PoolTransaction>::recover_raw_transaction(tx),\n        }\n        .map_err(Self::Error::from_eth_err)\n    }","sourceUrl":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc-eth-api/src/helpers/transaction.rs#L81-L109","contentHash":"d066febcf3cc92992a5addaa4c13654202cf6dd200054e0a4f9f37799aafe0ef","title":"デコードして送信者を復元","question":"バイト列は、どうプール用の型になる？","subtitle":"生のバイト列からプール用トランザクションを復元し、Local として次へ渡します。","symbol":"EthTransactions::send_raw_transaction","node":"デコード・送信者復元","short":"型と入力の確認","lines":[88,94],"summary":"復元に成功したトランザクションを、元のバイト列と組にして渡します。","detail":"recover_raw_pool_transaction はキャッシュ設定に応じた復元フックを選びます。次の send_pool_transaction には TransactionOrigin::Local を指定し、WithEncoded に元のバイト列と復元結果を持たせます。","input":"Bytes と &self","output":"Result<B256, Self::Error> を返す Future","side":"設定に応じた復元処理、送信処理への委譲","branch":"復元の失敗時は ? で早期終了し、send_pool_transaction を呼びません。キャッシュの有無で呼ぶ復元フックが変わります。","concept":"&tx / async move / impl Future","language":"&tx は値を借用します。async move は使う値を非同期ブロックへ取り込みます。戻り値の impl Future は具体的な型名を隠しつつ、Future を返すことを表します。","compare":"TypeScript の型注釈と異なり、Rust の借用は所有権に関わる制約です。Future は通常、ポーリングされて処理が進みます。","doc":"https://doc.rust-lang.org/book/ch17-01-futures-and-syntax.html","related":"recovery-hook","group":"DECODE","edge":"EthApi の実装へ","edgeLine":90},{"id":"submit","path":"crates/rpc/rpc/src/eth/helpers/transaction.rs","file":"transaction.rs","start":32,"end":114,"code":"    async fn send_pool_transaction(\n        &self,\n        origin: reth_transaction_pool::TransactionOrigin,\n        tx: WithEncoded<PoolTx<Self::Pool>>,\n    ) -> Result<B256, Self::Error> {\n        let (tx, mut pool_transaction) = tx.split();\n\n        // Optionally convert legacy blob sidecars to EIP-7594 format when Osaka is active\n        // This is opt-in via --rpc.force-blob-sidecar-upcasting\n        if self.inner.force_blob_sidecar_upcasting() && pool_transaction.is_eip4844() {\n            let EthBlobTransactionSidecar::Present(sidecar) = pool_transaction.take_blob() else {\n                return Err(EthApiError::PoolError(RpcPoolError::Eip4844(\n                    Eip4844PoolTransactionError::MissingEip4844BlobSidecar,\n                )));\n            };\n            let sidecar = sidecar.into_sidecar();\n\n            let sidecar = match sidecar {\n                BlobTransactionSidecarVariant::Eip4844(sidecar) => {\n                    let latest = self\n                        .provider()\n                        .latest_header()?\n                        .ok_or(EthApiError::HeaderNotFound(BlockId::latest()))?;\n                    // Convert to EIP-7594 if next block is Osaka\n                    if self\n                        .provider()\n                        .chain_spec()\n                        .is_osaka_active_at_timestamp(latest.timestamp().saturating_add(12))\n                    {\n                        BlobTransactionSidecarVariant::Eip7594(\n                            self.blob_sidecar_converter().convert(sidecar).await.ok_or_else(\n                                || {\n                                    RpcPoolError::Eip4844(\n                                        Eip4844PoolTransactionError::InvalidEip4844Blob(\n                                            BlobTransactionValidationError::InvalidProof,\n                                        ),\n                                    )\n                                },\n                            )?,\n                        )\n                    } else {\n                        BlobTransactionSidecarVariant::Eip4844(sidecar)\n                    }\n                }\n                sidecar => sidecar,\n            };\n\n            pool_transaction =\n                EthPoolTransaction::try_from_eip4844(pool_transaction.into_consensus(), sidecar)\n                    .ok_or_else(|| {\n                        RpcPoolError::Eip4844(\n                            Eip4844PoolTransactionError::MissingEip4844BlobSidecar,\n                        )\n                    })?;\n        }\n\n        // forward the transaction to the specific endpoint if configured.\n        if let Some(client) = self.raw_tx_forwarder() {\n            tracing::debug!(target: \"rpc::eth\", hash = %pool_transaction.hash(), \"forwarding raw transaction to forwarder\");\n            let rlp_hex = hex::encode_prefixed(&tx);\n\n            // broadcast raw transaction to subscribers if there is any.\n            self.broadcast_raw_transaction(tx);\n\n            let hash =\n                client.request(\"eth_sendRawTransaction\", (rlp_hex,)).await.inspect_err(|err| {\n                    tracing::debug!(target: \"rpc::eth\", %err, hash=% *pool_transaction.hash(), \"failed to forward raw transaction\");\n                }).map_err(EthApiError::other)?;\n\n            // Retain tx in local tx pool after forwarding, for local RPC usage.\n            let _ = self.inner.add_pool_transaction(origin, pool_transaction).await;\n\n            return Ok(hash);\n        }\n\n        // broadcast raw transaction to subscribers if there is any.\n        self.broadcast_raw_transaction(tx);\n\n        let AddedTransactionOutcome { hash, .. } =\n            self.inner.add_pool_transaction(origin, pool_transaction).await?;\n\n        Ok(hash)\n    }","sourceUrl":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc/src/eth/helpers/transaction.rs#L32-L114","contentHash":"866ae7cc641b85c2d06260abf471913d5741ef54e97838fe4f8f991c6ab7cd17","title":"通常の送信経路を追う","question":"どの条件で、ローカルのプールへ進む？","subtitle":"転送先なし・blob 変換対象外の経路に注目します。省略箇所は展開できます。","symbol":"EthApi::send_pool_transaction","node":"通常経路を選ぶ","short":"転送先の有無で分岐","lines":[107,113],"folds":[[39,86],[88,105]],"summary":"通常経路では購読者へ通知し、プールへの追加結果を待ちます。","detail":"WithEncoded を分解した後、設定次第で blob sidecar の変換や外部 RPC への転送に分岐します。ここでは転送先がない経路を読み、add_pool_transaction の成功結果から hash を取り出します。","input":"origin と WithEncoded<PoolTx<Self::Pool>>","output":"成功時はプール追加結果の hash","side":"raw transaction 購読者への通知、追加要求","branch":"転送先があれば別経路で早期 return します。通常経路の追加失敗は ? で返ります。購読者への通知を P2P 伝播の完了と混同しないでください。","concept":"構造体パターン { hash, .. }","language":"AddedTransactionOutcome { hash, .. } は構造体を分解して hash を取り出します。.. は残りのフィールドを指定しないことを表します。","compare":"TypeScript のオブジェクト分割代入に似ていますが、Rust ではフィールドの所有権や借用も考慮します。","doc":"https://doc.rust-lang.org/book/ch19-03-pattern-syntax.html","related":"forward","group":"BRANCH","edge":"追加要求を作る","edgeLine":111},{"id":"queue","path":"crates/rpc/rpc/src/eth/core.rs","file":"core.rs","start":489,"end":504,"code":"    /// Adds an _unvalidated_ transaction into the pool via the transaction batch sender.\n    #[inline]\n    pub async fn add_pool_transaction(\n        &self,\n        origin: reth_transaction_pool::TransactionOrigin,\n        transaction: <N::Pool as TransactionPool>::Transaction,\n    ) -> Result<AddedTransactionOutcome, EthApiError> {\n        let (response_tx, response_rx) = tokio::sync::oneshot::channel();\n        let request = reth_transaction_pool::BatchTxRequest::new(origin, transaction, response_tx);\n\n        self.tx_batch_sender()\n            .send(request)\n            .map_err(|_| reth_rpc_eth_types::EthApiError::BatchTxSendError)?;\n\n        Ok(response_rx.await??)\n    }","sourceUrl":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc/src/eth/core.rs#L489-L504","contentHash":"fd159467b7670555e1ab3e3663276a187ca277d261c29e6b27f1f7dbb37cd512","title":"追加要求をチャネルへ送る","question":"RPC は、プールへの追加をどう待つ？","subtitle":"要求を送るチャネルと、結果を一度だけ受け取るチャネルを分けて読みます。","symbol":"EthApiInner::add_pool_transaction","node":"要求と応答をつなぐ","short":"チャネルと二重の Result","lines":[496,503],"summary":"バッチ処理へ要求を送り、oneshot で個別の結果を待ちます。","detail":"response_tx を要求に添えて tx_batch_sender に送ります。RPC 側は response_rx を保持し、処理側から追加結果が戻るのを待ちます。このメソッド自身はトランザクションの検証を実行していません。","input":"未検証トランザクションと origin","output":"Result<AddedTransactionOutcome, EthApiError>","side":"バッチ処理の要求キューへの送信","branch":"send 失敗は BatchTxSendError。await?? の一つ目は受信失敗、二つ目は届いた追加結果の失敗を伝播します。","concept":"oneshot / .await??","language":"oneshot は一度だけ結果を送受信するチャネルです。ここで await の結果は Result の中に Result を持つため、? を二回適用してそれぞれの失敗を処理します。","compare":"Promise の resolve 用コールバックを渡す構成に似ていますが、送信側・受信側が明示的な型に分かれ、チャネル切断も結果として扱います。","doc":"https://docs.rs/tokio/latest/tokio/sync/oneshot/index.html","related":"batch-runner","group":"CHANNEL","edge":"チャネル経由で受信","edgeLine":500},{"id":"batch","path":"crates/transaction-pool/src/batcher.rs","file":"batcher.rs","start":69,"end":105,"code":"    async fn process_request(pool: &Pool, req: BatchTxRequest<Pool::Transaction>) {\n        let BatchTxRequest { origin, pool_tx, response_tx } = req;\n        let pool_result = pool.add_transaction(origin, pool_tx).await;\n        let _ = response_tx.send(pool_result);\n    }\n\n    /// Process a batch of transaction requests with per-transaction origins\n    async fn process_batch(pool: &Pool, batch: Vec<BatchTxRequest<Pool::Transaction>>) {\n        if batch.len() == 1 {\n            Self::process_request(pool, batch.into_iter().next().expect(\"batch is not empty\"))\n                .await;\n            return\n        }\n\n        // Same-origin batches can skip the per-transaction origins allocation.\n        let mut batch_iter = batch.iter();\n        if let Some(origin) = batch_iter.next().map(|req| req.origin) &&\n            batch_iter.all(|req| req.origin == origin)\n        {\n            let (transactions, response_txs): (Vec<_>, Vec<_>) =\n                batch.into_iter().map(|req| (req.pool_tx, req.response_tx)).unzip();\n\n            let pool_results = pool.add_transactions(origin, transactions).await;\n            for (response_tx, pool_result) in response_txs.into_iter().zip(pool_results) {\n                let _ = response_tx.send(pool_result);\n            }\n            return\n        }\n\n        let (transactions, response_txs): (Vec<_>, Vec<_>) =\n            batch.into_iter().map(|req| ((req.origin, req.pool_tx), req.response_tx)).unzip();\n\n        let pool_results = pool.add_transactions_with_origins(transactions).await;\n        for (response_tx, pool_result) in response_txs.into_iter().zip(pool_results) {\n            let _ = response_tx.send(pool_result);\n        }\n    }","sourceUrl":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/transaction-pool/src/batcher.rs#L69-L105","contentHash":"651fd1d5815a1733309eba00584f2a24807211cfcce73c75598fbe3738163262","title":"バッチをプールへ引き渡す","question":"要求はいつ、一件または複数件で処理される？","subtitle":"一件・同じ origin・異なる origin の三つの分岐を確認します。","symbol":"BatchTxProcessor::process_batch","node":"まとめて引き渡す","short":"一件とバッチの分岐","lines":[77,94],"summary":"要求の件数と origin に合わせて、プールの追加メソッドを選びます。","detail":"一件なら process_request → add_transaction、同じ origin の複数件なら add_transactions、混在時は add_transactions_with_origins を呼びます。各要求に添えられた response_tx に結果を戻します。","input":"Vec<BatchTxRequest<Pool::Transaction>>","output":"各要求の oneshot にプールの結果を返す","side":"検証・追加の委譲、応答チャネルへの送信","branch":"response_tx.send の結果は let _ で捨てています。受信側がなくても、この箇所ではエラーを上へ返しません。","concept":"into_iter / unzip / zip","language":"into_iter はコレクションを消費する反復を行います。ここで unzip はトランザクションと返信先を二つの Vec に分け、zip は各結果と返信先を順に組にします。","compare":"TypeScript の map で複数配列を作る考え方に近いですが、into_iter は元のコレクションの所有権を消費します。","doc":"https://doc.rust-lang.org/std/iter/trait.Iterator.html#method.unzip","related":"batch-runner","group":"BATCH","edge":"検証付き API へ","edgeLine":91},{"id":"pool","path":"crates/transaction-pool/src/lib.rs","file":"lib.rs","start":495,"end":528,"code":"    async fn add_transaction(\n        &self,\n        origin: TransactionOrigin,\n        transaction: Self::Transaction,\n    ) -> PoolResult<AddedTransactionOutcome> {\n        let tx = self.validate(origin, transaction).await;\n        let mut results = self.pool.add_transactions(origin, std::iter::once(tx));\n        results.pop().expect(\"result length is the same as the input\")\n    }\n\n    async fn add_transactions(\n        &self,\n        origin: TransactionOrigin,\n        transactions: Vec<Self::Transaction>,\n    ) -> Vec<PoolResult<AddedTransactionOutcome>> {\n        if transactions.is_empty() {\n            return Vec::new()\n        }\n        let validated =\n            self.pool.validator().validate_transactions_with_origin(origin, transactions).await;\n        self.pool.add_transactions(origin, validated)\n    }\n\n    async fn add_transactions_with_origins(\n        &self,\n        transactions: Vec<(TransactionOrigin, Self::Transaction)>,\n    ) -> Vec<PoolResult<AddedTransactionOutcome>> {\n        if transactions.is_empty() {\n            return Vec::new()\n        }\n        let origins: Vec<_> = transactions.iter().map(|(origin, _)| *origin).collect();\n        let validated = self.pool.validator().validate_transactions(transactions).await;\n        self.pool.add_transactions_with_origins(origins.into_iter().zip(validated))\n    }","sourceUrl":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/transaction-pool/src/lib.rs#L495-L528","contentHash":"87582b4a22dc8ac527f8380847cec7d6dcc133c0e12ff281034d3a6252df1443","title":"検証してプールに追加","question":"成功したら、すでにチェーンへ記録された？","subtitle":"プールへの追加と、ブロックへの取り込みを区別して読解を締めくくります。","symbol":"Pool::add_transaction","node":"検証・プール追加","short":"ハッシュと確定の違い","lines":[495,502],"folds":[[518,527]],"summary":"検証結果を内部プールへ渡し、追加の成否を返します。","detail":"単件・複数件ともに検証を経由して内部プールへ渡します。単件では結果リストから一件を取り出します。この経路はレシートやブロック取り込みを待つ処理ではありません。","input":"未検証トランザクションと origin","output":"PoolResult<AddedTransactionOutcome>","side":"検証処理、内部プールの更新","branch":"検証結果を内部プールが扱い、追加結果を返します。結果リストが空なら expect は panic します。検証器の具体的な条件はこの抜粋の外です。","concept":"Self::Transaction / expect","language":"Self::Transaction は、この実装が使う関連型です。expect は値が存在すれば取り出し、存在しなければ指定メッセージで panic します。? によるエラー伝播とは挙動が違います。","compare":"TypeScript の非 null アサーション ! は実行時検証をしません。Rust の expect は実行時に失敗を検出し、panic します。","doc":"https://doc.rust-lang.org/book/ch09-02-recoverable-errors-with-result.html","related":"pool-test","group":"POOL","edge":"","edgeLine":500}],"details":[{"id":"rpc-contract","path":"crates/rpc/rpc-eth-api/src/core.rs","file":"core.rs","start":380,"end":390,"code":"    /// Sends signed transaction, returning its hash.\n    #[method(name = \"sendRawTransaction\")]\n    async fn send_raw_transaction(&self, bytes: Bytes) -> RpcResult<B256>;\n\n    /// Sends a signed transaction and awaits the transaction receipt.\n    ///\n    /// This will return a timeout error if the transaction isn't included within some time period.\n    #[method(name = \"sendRawTransactionSync\")]\n    async fn send_raw_transaction_sync(\n        &self,\n        bytes: Bytes,","sourceUrl":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc-eth-api/src/core.rs#L380-L390","contentHash":"cca25d2d19f1371060230f53812138c79d0c586e5ec985920a6fe39f57f30d0b","title":"RPC の公開インターフェース","question":"通常版と Sync 版は、何を返す？","subtitle":"公開メソッドの宣言とコメントを比較します。","symbol":"EthApiServer interface","node":"RPC 定義","short":"ハッシュとレシート","lines":[380,386],"summary":"通常版はハッシュを返し、Sync 版はレシートを待つと定義されています。","detail":"sendRawTransaction と sendRawTransactionSync は別メソッドです。Sync 版のコメントには、一定時間内に取り込まれなければタイムアウトになることも記されています。","input":"署名済みトランザクション","output":"通常版：B256、Sync 版：レシート","side":"ここはインターフェース宣言","branch":"宣言から挙動の契約を確認できます。実行した結果ではありません。","concept":"#[method(...)]","language":"#[...] は属性です。この method 属性は RPC 用マクロのための情報で、公開されるメソッド名を指定しています。","compare":"TypeScript のデコレーターと見た目は似ていますが、Rust の属性マクロはコンパイル時のコード生成などに使われます。","doc":"https://doc.rust-lang.org/book/ch20-05-macros.html"},{"id":"recovery-hook","path":"crates/transaction-pool/src/traits.rs","file":"traits.rs","start":1429,"end":1466,"code":"\n    /// Decodes and recovers a raw transaction into this pool transaction type.\n    ///\n    /// Implementations can override this to avoid constructing the pooled transaction as an\n    /// intermediate value when the raw representation can be converted directly into `Self`.\n    /// RPC uses this hook when no sender recovery cache is configured. Override\n    /// [`Self::recover_raw_transaction_with_cache`] to specialize the cached path as well.\n    fn recover_raw_transaction(data: &[u8]) -> Result<Self, RawPoolTransactionError> {\n        Self::try_recover(Self::decode_raw_transaction(data)?)\n            .map_err(|_| RawPoolTransactionError::InvalidTransactionSignature)\n    }\n\n    /// Decodes and recovers a raw pool transaction using the provided sender recovery cache.\n    ///\n    /// RPC uses this hook when a sender recovery cache is configured. Implementations can override\n    /// it to reuse the raw bytes or encoded length during recovery and construction. The default\n    /// implementation decodes and recovers separately; it does not call\n    /// [`Self::recover_raw_transaction`].\n    fn recover_raw_transaction_with_cache(\n        data: &[u8],\n        cache: &reth_evm::SenderRecoveryCache,\n    ) -> Result<Self, RawPoolTransactionError> {\n        Self::try_recover_with_cache(Self::decode_raw_transaction(data)?, cache)\n            .map_err(|_| RawPoolTransactionError::InvalidTransactionSignature)\n    }\n\n    /// Decodes a raw pooled transaction without recovering its sender.\n    ///\n    /// The entire input must be consumed; trailing bytes are rejected. Implementations can override\n    /// this to customize raw decoding independently of sender recovery.\n    fn decode_raw_transaction(data: &[u8]) -> Result<Self::Pooled, RawPoolTransactionError> {\n        if data.is_empty() {\n            return Err(RawPoolTransactionError::EmptyRawTransactionData)\n        }\n\n        Self::Pooled::decode_2718_exact(data)\n            .map_err(|_| RawPoolTransactionError::FailedToDecodeSignedTransaction)\n    }","sourceUrl":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/transaction-pool/src/traits.rs#L1429-L1466","contentHash":"b3416b3c7c92c93a95765a63213319f6d56974a1cfca3eaf546e6901f696b27f","title":"デフォルトの復元フック","question":"どんな入力が、デコードで拒否される？","subtitle":"PoolTransaction trait のデフォルト実装を確認します。具象型による上書きが可能です。","symbol":"PoolTransaction::recover_raw_transaction","node":"復元フック","short":"デコードと署名の失敗","lines":[1458,1465],"summary":"デフォルト実装は空データを拒否し、デコードと送信者復元を行います。","detail":"decode_2718_exact の失敗と、try_recover の失敗を別のエラーに変換します。これは trait のデフォルト実装であり、すべてのプール型が必ずこの本体を使うとは限りません。","input":"&[u8]：バイト列の借用","output":"復元された Self または RawPoolTransactionError","side":"デコード・送信者復元","branch":"空データ、デコード失敗、署名復元失敗を区別します。キャッシュありのフックも別にあります。","concept":"&[u8] / Self / map_err","language":"&[u8] はバイト列を借用するスライスです。Self はこの trait を実装する型を指します。map_err は Result のエラー側の値を変換します。","compare":"Uint8Array を渡す感覚に近いですが、Rust の参照には借用と有効期間の制約があります。","doc":"https://doc.rust-lang.org/book/ch04-02-references-and-borrowing.html"},{"id":"forward","path":"crates/rpc/rpc/src/eth/helpers/transaction.rs","file":"transaction.rs","start":88,"end":105,"code":"        // forward the transaction to the specific endpoint if configured.\n        if let Some(client) = self.raw_tx_forwarder() {\n            tracing::debug!(target: \"rpc::eth\", hash = %pool_transaction.hash(), \"forwarding raw transaction to forwarder\");\n            let rlp_hex = hex::encode_prefixed(&tx);\n\n            // broadcast raw transaction to subscribers if there is any.\n            self.broadcast_raw_transaction(tx);\n\n            let hash =\n                client.request(\"eth_sendRawTransaction\", (rlp_hex,)).await.inspect_err(|err| {\n                    tracing::debug!(target: \"rpc::eth\", %err, hash=% *pool_transaction.hash(), \"failed to forward raw transaction\");\n                }).map_err(EthApiError::other)?;\n\n            // Retain tx in local tx pool after forwarding, for local RPC usage.\n            let _ = self.inner.add_pool_transaction(origin, pool_transaction).await;\n\n            return Ok(hash);\n        }","sourceUrl":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc/src/eth/helpers/transaction.rs#L88-L105","contentHash":"17d1ea7cc58e3ebd06e114620b397fb1cccc2fe0c1620fc0d7acca0ae7f862ff","title":"転送先ありの分岐","question":"外部へ転送した後、ローカル追加が失敗したら？","subtitle":"通常経路とは異なる成功条件を持つ分岐へ寄り道します。","symbol":"send_pool_transaction → forwarder","node":"外部 RPC へ転送","short":"エラーの扱いを比較","lines":[96,104],"summary":"転送が成功すれば、ローカル追加の失敗を返さずに転送先のハッシュを返します。","detail":"外部 RPC の request は await と ? で失敗を伝播します。一方、後続の add_pool_transaction の結果は let _ で捨てています。通常経路の await? と比較するのが読解のポイントです。","input":"設定された RPC クライアントとトランザクション","output":"転送先が返した hash","side":"購読者通知、外部 RPC 呼び出し、ローカル追加の試行","branch":"外部への転送失敗はエラー。転送成功後のローカル追加失敗は、この分岐の返却結果に反映されません。","concept":"if let Some / let _ =","language":"if let Some(client) は Option が Some のときだけ中の値を取り出します。let _ = は式の結果を保持しません。ここでは Result の成功・失敗を検査していません。","compare":"TypeScript の if (client) に近い分岐ですが、Option の Some/None を明示的に扱います。結果を捨てる処理と ? の伝播を区別しましょう。","doc":"https://doc.rust-lang.org/book/ch06-03-if-let.html"},{"id":"batch-runner","path":"crates/transaction-pool/src/batcher.rs","file":"batcher.rs","start":114,"end":135,"code":"    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {\n        let mut this = self.project();\n\n        loop {\n            // Drain all available requests from the receiver\n            ready!(this.request_rx.poll_recv_many(cx, this.buf, *this.max_batch_size));\n\n            if !this.buf.is_empty() {\n                let batch = std::mem::take(this.buf);\n                let pool = this.pool.clone();\n                tokio::spawn(async move {\n                    Self::process_batch(&pool, batch).await;\n                });\n                this.buf.reserve(1);\n\n                continue;\n            }\n\n            // No requests available, return Pending to wait for more\n            return Poll::Pending;\n        }\n    }","sourceUrl":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/transaction-pool/src/batcher.rs#L114-L135","contentHash":"0e804cb18f0af19cb16042b3321d50a2c924f21c33eb97c127062976075fa041","title":"受信側のタスクを読む","question":"キューの向こう側は、どこで動く？","subtitle":"BatchTxProcessor の Future 実装から、要求の受信と処理の起動を確認します。","symbol":"BatchTxProcessor::poll","node":"受信タスク","short":"非同期の境界","lines":[118,126],"summary":"利用可能な要求を受け取り、まとめて処理する非同期タスクを起動します。","detail":"poll_recv_many で受け取った要求を buf に蓄え、空でなければ取り出します。pool のハンドルを clone して tokio::spawn の中で process_batch を待ちます。","input":"要求チャネルとバッファ","output":"Poll<()>","side":"受信、バッファの移動、タスクの起動","branch":"ready! は未準備なら Pending を返します。spawn はタスクを起動しますが、ここから常に専用スレッドが作られるとは言えません。","concept":"poll / ready! / tokio::spawn","language":"Future は poll によって進みます。Pending はまだ完了していない状態です。tokio::spawn はランタイムへ非同期タスクを登録し、その処理をスケジュールさせます。","compare":"JavaScript のイベントループと似た待機・再開の考え方がありますが、Rust は Future の poll とランタイムの役割を分けて扱います。","doc":"https://docs.rs/tokio/latest/tokio/task/fn.spawn.html"},{"id":"pool-test","path":"crates/rpc/rpc/src/eth/helpers/transaction.rs","file":"transaction.rs","start":349,"end":362,"code":"    #[tokio::test]\n    async fn send_raw_transaction() {\n        let eth_api = mock_eth_api(Default::default());\n        let pool = eth_api.pool();\n\n        let tx_1 = raw_transfer_tx();\n\n        let tx_1_result = eth_api.send_raw_transaction(tx_1).await.unwrap();\n        assert_eq!(\n            pool.len(),\n            1,\n            \"expect 1 transaction in the pool, but pool size is {}\",\n            pool.len()\n        );","sourceUrl":"https://github.com/paradigmxyz/reth/blob/3d592ece6de8c4559987416a544fc215fd6d6921/crates/rpc/rpc/src/eth/helpers/transaction.rs#L349-L362","contentHash":"d846f899697a9dc98775def30f182d904bd9ae9f373b3452fde54823da05e507","title":"既存テストを根拠に読む","question":"このテストは、どこまで確かめている？","subtitle":"テストコードの一部を読みます。このモックではテストを実行していません。","symbol":"tests::send_raw_transaction","node":"既存テスト","short":"期待する挙動の確認","lines":[350,362],"summary":"送信後にプール内の件数が 1 になることを、テストが期待しています。","detail":"mock_eth_api からプールを取得し、raw_transfer_tx を送った後に pool.len() を比較しています。これはテストの記述を読んだ根拠であり、この環境での実行成功やメインネットでの動作を示すものではありません。","input":"テスト用の API と raw transaction","output":"assert_eq! による件数の検査","side":"テスト用プールへの追加","branch":"unwrap はエラー時に panic します。抜粋の後には二件目の送信・取得・Local origin の検査が続きます。","concept":"#[tokio::test] / assert_eq!","language":"#[tokio::test] は非同期テスト用の属性です。assert_eq! は二つの値が等しいことを検査し、違えば panic します。","compare":"Vitest などの expect に近い役割ですが、! が付く assert_eq! は Rust のマクロです。","doc":"https://doc.rust-lang.org/book/ch11-01-writing-tests.html"}],"license":{"name":"MIT","copyright":"Copyright (c) 2022-2026 Reth Contributors","text":"The MIT License (MIT)\n\nCopyright (c) 2022-2026 Reth Contributors\n\nPermission is hereby granted, free of charge, to any person obtaining a copy\nof this software and associated documentation files (the \"Software\"), to deal\nin the Software without restriction, including without limitation the rights\nto use, copy, modify, merge, publish, distribute, sublicense, and/or sell\ncopies of the Software, and to permit persons to whom the Software is\nfurnished to do so, subject to the following conditions:\n\nThe above copyright notice and this permission notice shall be included in\nall copies or substantial portions of the Software.\n\nTHE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\nIMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\nFITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\nAUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\nLIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\nOUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN\nTHE SOFTWARE.\n"},"version":"v2.7.0"};
